//! 🎟️ One scalar frontier retains the actual receipt until its resident guest loan is returned.
use semio_framework_actor::{OriginalGuestExecutionBudget,OriginalGuestExecutionReceipt};
use semio_framework_job::{OriginalTurnFailure,StepContext};
use semio_framework_value::{RetainedCloneProgress,ValueError,ValueRefusalKind};
use semio_plugin_host_guest_runtime::{GuestInstance,GuestRuntimes,OriginalCoreValue,OwnedOriginalCallProgress,OwnedOriginalCallResult,OwnedOriginalCallStatus,OwnedSemioExport};
use semio_plugin_guest_contract::operation_authority::owned_result::{self,OwnedReturn};
use std::mem::{ManuallyDrop,size_of};
#[derive(Clone,Copy,PartialEq,Eq)]
enum Phase{Begin,Drive,Frozen,Take,Borrow,Escrow,ReleaseBegin,ReleaseDrive,ReleaseTake,Complete,Closing}
pub struct GuestRelayScalarFlow{export:OwnedSemioExport,args:[OriginalCoreValue;OwnedSemioExport::MAX_SCALAR_ARGUMENTS],count:usize,prepared:Option<u64>,closed:bool,page:bool,phase:Phase,pointer:u32,length:usize,receipt:[u8;184],progress:ManuallyDrop<Option<OwnedOriginalCallProgress>>,received:Option<OwnedOriginalCallResult>}
impl GuestRelayScalarFlow{
 pub fn new(export:OwnedSemioExport,args:&[OriginalCoreValue])->Result<Self,ValueError>{if args.len()>OwnedSemioExport::MAX_SCALAR_ARGUMENTS{return Err(refused("scalar arguments exceed their fixed ABI"))}let mut fixed=[OriginalCoreValue::I64(0);OwnedSemioExport::MAX_SCALAR_ARGUMENTS];fixed[..args.len()].copy_from_slice(args);Ok(Self{export,args:fixed,count:args.len(),prepared:None,closed:false,page:false,phase:Phase::Begin,pointer:0,length:0,receipt:[0;184],progress:ManuallyDrop::new(None),received:None})}
 /// 📄️ Starts a scalar frontier whose guest byte result is a raw page extent, never an escrowed receipt.
 pub fn page(export:OwnedSemioExport,args:&[OriginalCoreValue])->Result<Self,ValueError>{let mut flow=Self::new(export,args)?;flow.page=true;Ok(flow)}
 /// 📏️ Names the completed guest page extent without copying its bytes.
 pub fn page_extent(&self)->Option<(u32,usize)>{(self.page&&self.phase==Phase::Complete).then_some((self.pointer,self.length))}
 pub fn requires_execution(&self,runtime:&GuestRuntimes,instance:&GuestInstance)->Result<bool,OriginalTurnFailure>{if matches!(self.phase,Phase::Drive|Phase::ReleaseDrive){runtime.original_scalar_requires_execution(instance)}else{Ok(false)}}
 /// 🪙️ Charges metadata before narrowing this callback's actual VM authorization.
 pub fn prepare_execution_step(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let epoch=cx.original_source_epoch().ok_or_else(||refused("scalar execution requires its Source epoch"))?;if self.prepared==Some(epoch){return Ok(true)}if !matches!(self.phase,Phase::Drive|Phase::ReleaseDrive)||self.failure().is_some(){return Err(refused("scalar execution is not pending").into())}let grant=cx.retained_grant();let bytes=size_of::<Option<u64>>()+size_of::<Option<OwnedOriginalCallProgress>>();if (if cx.original_retirement_active(){cx.retirement_should_yield()}else{cx.should_yield()})||grant.maximum_items==0||grant.maximum_copy_bytes<bytes||grant.maximum_depth==0{return Ok(false)}cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:bytes,..Default::default()})?;cx.consume_fuel(1);self.progress.take();self.prepared=Some(epoch);Ok(true)}
 pub fn execution_receipt(&self)->Option<OriginalGuestExecutionReceipt>{self.progress.as_ref().and_then(|reply|reply.execution)}
 pub fn failure(&self)->Option<&OriginalTurnFailure>{self.progress.as_ref().and_then(|reply|reply.result.as_ref().err())}
 pub fn bytes(&self)->Option<&[u8]>{(!self.page&&self.phase==Phase::Complete).then(||&self.receipt[..self.length])}
 /// ▶️ One actual Core phase retains the whole returned progress before any validation or guest loan handback.
 pub fn advance(&mut self,runtime:&GuestRuntimes,instance:&mut GuestInstance,execution:Option<OriginalGuestExecutionBudget>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
  runtime.original_scalar_export(instance,cx)?;
  if self.failure().is_some(){return Err(refused("scalar failure remains in its original owner").into())}if matches!(self.phase,Phase::Take|Phase::ReleaseTake){if execution.is_some(){return Err(refused("scalar receiving cannot issue VM credit").into())}if self.received.is_none(){runtime.take_original_scalar_into_step(instance,&mut self.received,cx)?;return Ok(false)}let result=self.received.as_ref().unwrap();let(pointer,length,phase)=if self.phase==Phase::ReleaseTake{if result.value.is_some(){return Err(refused("resident receipt handback returned a value").into())}(self.pointer,self.length,Phase::Complete)}else{let Some(OriginalCoreValue::I64(word))=result.value else{return Err(refused("scalar receipt has no original word").into())};match owned_result::decode(word as u64)?{OwnedReturn::Bytes{pointer,length}if self.page=>(pointer,length as usize,Phase::Complete),OwnedReturn::Bytes{pointer,length}if matches!(length,144|184)=>(pointer,length as usize,Phase::Borrow),OwnedReturn::Refusal(kind)=>return Err(ValueError::literal(kind,"scalar guest refused its call").into()),_=>return Err(refused("scalar receipt has an unexpected resident extent").into())}};let changed=self.phase==Phase::Take;let items=2+2*usize::from(changed)+usize::from(self.progress.is_some());let bytes=size_of::<Option<OwnedOriginalCallResult>>()+size_of::<Phase>()+if changed{size_of::<u32>()+size_of::<usize>()}else{0}+if self.progress.is_some(){size_of::<Option<OwnedOriginalCallProgress>>()}else{0};let g=cx.retained_grant();if cx.retirement_should_yield()||g.maximum_items<items||g.maximum_copy_bytes<bytes||g.maximum_depth==0||cx.fuel_remaining()<items as u64{return Ok(false)}cx.consume_retained(RetainedCloneProgress{copied_items:items,copied_bytes:bytes,..Default::default()})?;cx.consume_fuel(items as u64);self.received=None;if self.progress.is_some(){self.progress.take();}if changed{self.pointer=pointer;self.length=length;}self.phase=phase;return Ok(self.phase==Phase::Complete)}if matches!(self.phase,Phase::Frozen|Phase::Escrow){return Err(refused("resident header awaits its authenticated escrow capture").into())}
  if execution.is_some(){if self.prepared!=cx.original_source_epoch(){return Err(refused("scalar execution was not prepared on this callback").into())}}else{if (if cx.original_retirement_active(){cx.retirement_should_yield()}else{cx.should_yield()}){return Ok(false)}let grant=cx.retained_grant();let bytes=size_of::<Phase>()+size_of::<Option<OwnedOriginalCallProgress>>();if grant.maximum_items==0||grant.maximum_copy_bytes<bytes||grant.maximum_depth==0{return Ok(false)}cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:bytes,..Default::default()})?;cx.consume_fuel(1);}
  self.prepared=None;self.progress.take();
  match self.phase{
   Phase::Begin=>{if execution.is_some(){return Err(refused("unstarted scalar cannot receive VM credit").into())}if runtime.begin_original_scalar_step(instance,self.export,&self.args[..self.count],cx)?{self.phase=Phase::Drive}},
   Phase::Drive|Phase::ReleaseDrive=>{let release=self.phase==Phase::ReleaseDrive;let mut reply=runtime.advance_original_scalar_step(instance,execution,cx)?;let ready=reply.result.as_ref().is_ok_and(|status|*status==OwnedOriginalCallStatus::Ready);if matches!(&reply.result,Ok(OwnedOriginalCallStatus::Cancelled)){reply.result=Err(ValueError::literal(ValueRefusalKind::Canceled,"scalar guest observed its actual cancellation").into())}else if matches!(&reply.result,Ok(OwnedOriginalCallStatus::Deadline)){reply.result=Err(ValueError::literal(ValueRefusalKind::WorkLimit,"scalar guest reached its actual deadline").into())}*self.progress=Some(reply);if ready{self.phase=if release{Phase::ReleaseTake}else if self.page{Phase::Take}else{Phase::Frozen}}},
   Phase::Frozen=>return Err(refused("resident header awaits its authenticated escrow capture").into()),
   Phase::Take=>unreachable!(),
   Phase::Borrow=>{let grant=cx.retained_grant();if grant.maximum_items==0||grant.maximum_copy_bytes<self.length||grant.maximum_depth==0{return Ok(false)}runtime.with_original_scalar_bytes(instance,self.pointer,self.length,cx,|bytes,cx|{cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:bytes.len(),..Default::default()})?;self.receipt[..bytes.len()].copy_from_slice(bytes);Ok(())})?;self.phase=Phase::Escrow},
   Phase::Escrow=>return Err(refused("resident header awaits its authenticated escrow capture").into()),
   Phase::ReleaseBegin=>{let args=[OriginalCoreValue::I32(self.pointer as i32),OriginalCoreValue::I32(self.length as i32)];if runtime.begin_original_scalar_step(instance,OwnedSemioExport::Deallocate,&args,cx)?{self.phase=Phase::ReleaseDrive}},
   Phase::ReleaseTake=>unreachable!(),
   Phase::Complete=>return Ok(true),Phase::Closing=>return Err(refused("closing scalar cannot resume").into())
  }Ok(self.phase==Phase::Complete)
 }
 /// 🧾️ Malformed returned DATA stays owned until an explicit retained recipient takes it.
 pub fn received_result(&self)->Option<&OwnedOriginalCallResult>{self.received.as_ref()}
 pub fn take_received_into_step(&mut self,runtime:&GuestRuntimes,instance:&GuestInstance,out:&mut Option<OwnedOriginalCallResult>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{runtime.original_scalar_export(instance,cx)?;if out.is_some(){return Err(refused("scalar result recipient is occupied").into())}if self.received.is_none(){return Ok(false)}let bytes=2*size_of::<Option<OwnedOriginalCallResult>>();let grant=cx.retained_grant();if cx.retirement_should_yield()||grant.maximum_items<2||grant.maximum_copy_bytes<bytes||grant.maximum_depth==0||cx.fuel_remaining()<2{return Ok(false)}cx.consume_retained(RetainedCloneProgress{copied_items:2,copied_bytes:bytes,..Default::default()})?;cx.consume_fuel(2);*out=self.received.take();Ok(true)}
 /// 📥️ Moves the complete original fault into a caller-retained owner before cleanup.
 pub fn take_failure_step(&mut self,cx:&mut StepContext<'_>,receive:impl FnOnce(&mut Option<OriginalTurnFailure>,&mut StepContext<'_>)->Result<(),OriginalTurnFailure>)->Result<bool,OriginalTurnFailure>{if self.failure().is_none(){return Ok(false)}let grant=cx.retained_grant();let bytes=size_of::<Option<OwnedOriginalCallProgress>>();if cx.retirement_should_yield()||grant.maximum_items==0||grant.maximum_copy_bytes<bytes||grant.maximum_depth==0{return Ok(false)}cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:bytes,..Default::default()})?;cx.consume_fuel(1);let reply=self.progress.take().unwrap();let mut failure=reply.result.err();let received=receive(&mut failure,cx);if let Some(error)=failure{*self.progress=Some(OwnedOriginalCallProgress{result:Err(error),execution:reply.execution});}received?;Ok(self.failure().is_none())}
 pub fn terminal_is_empty(&self)->bool{(matches!(self.phase,Phase::Begin|Phase::Complete)||self.phase==Phase::Closing&&self.closed)&&self.progress.is_none()&&self.received.is_none()}
 /// 🧹️ A partial machine aborts only for subsequent full original-instance retirement.
 pub fn close_step(&mut self,runtime:&GuestRuntimes,instance:&mut GuestInstance,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if matches!(self.phase,Phase::Frozen|Phase::Escrow){return Err(refused("resident header retains its uncaptured escrow").into())}if self.phase!=Phase::Closing{let grant=cx.retained_grant();if cx.retirement_should_yield()||grant.maximum_items==0||grant.maximum_copy_bytes<size_of::<Phase>()||grant.maximum_depth==0{return Ok(false)}cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:size_of::<Phase>(),..Default::default()})?;cx.consume_fuel(1);self.phase=Phase::Closing;}if runtime.original_scalar_is_pending(instance)?&&!runtime.close_original_scalar_step(instance,cx)?{return Ok(false)}if self.failure().is_some()||self.received.is_some(){return Err(refused("scalar failure or received result requires explicit controlled retirement").into())}self.progress.take();self.closed=true;Ok(true)}
}
impl Drop for GuestRelayScalarFlow{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original scalar requires paid completion or parent retirement");if self.progress.is_none(){unsafe{ManuallyDrop::drop(&mut self.progress)}}}}
fn refused(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,message)}
